<!DOCTYPE html>
<html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Limites - DFLG Investments</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?= URL_BASE ?>/assets/css/style.css" rel="stylesheet"></head>
<body><?php require __DIR__ . '/../partials/header.php'; ?><?php $limites = $limites ?? []; ?><div class="container pb-5"><h2 class="mb-4">Limites mensais por categoria</h2><div class="card shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Categoria</th><th>Gasto no mes</th><th>Limite</th><th>Atualizar</th></tr></thead><tbody><?php foreach ($limites as $limite): ?><tr><td><?= htmlspecialchars($limite['nome']) ?></td><td>R$ <?= number_format($limite['gasto_mes'], 2, ',', '.') ?></td><td><?= $limite['limite_mensal'] !== null ? 'R$ ' . number_format($limite['limite_mensal'], 2, ',', '.') : 'Nao definido' ?><?php if ($limite['limite_mensal'] !== null && $limite['gasto_mes'] > $limite['limite_mensal']): ?><span class="badge bg-danger ms-2">Excedido</span><?php endif; ?></td><td><form method="post" action="<?= URL_BASE ?>/limites/salvar" class="d-flex gap-2"><input type="hidden" name="categoriaId" value="<?= $limite['id'] ?>"><input class="form-control form-control-sm" type="number" step="0.01" min="0.01" name="limite" value="<?= $limite['limite_mensal'] ?? '' ?>" required><button class="btn btn-sm btn-primary">Salvar</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></body></html>